<template><AppShell title="我的订单" back tab="mine"><view class="pad" style="background:#fff;padding-bottom:5px"><view class="segmented"><button class="ui-button" :class="{selected:role==='buyer'}" @click="role='buyer';load()">我买到的</button><button class="ui-button" :class="{selected:role==='worker'}" @click="role='worker';load()">我卖出的</button></view><view class="search order-search"><input v-model="keyword" @blur="keyword=$event.detail.value" placeholder="搜索订单号或道具名称" maxlength="80" confirm-type="search" @confirm="keyword=$event.detail.value;load()" /><button class="ui-button text-button" @click="load()">搜索</button><button v-if="keyword" class="ui-button text-button" @click="keyword='';load()">清空</button></view></view><view class="tabs"><button class="ui-button" v-for="s in statuses" :key="s.value" :class="{selected:status===s.value}" @click="status=s.value;load()">{{s.label}}</button></view><view class="pad"><StateView :loading="loading" :error="error" :count="items.length" title="还没有相关订单" description="逛逛道具市场，或管理自己的在售商品" @retry="load()"><button class="ui-button btn small" @click="go(role==='buyer'?'market/index':'manage/index')">{{role==='buyer'?'逛逛市场':'我的商品'}}</button></StateView><view v-for="o in items" :key="o.id" class="card"><view class="row between"><view class="row flex-1 order-peer"><AppIcon class="app-icon" name="user" :size="24" /><text class="bold">{{role==='buyer'?o.workerName:o.buyerName}}</text></view><text class="tag" :class="{gray:['COMPLETED','CANCELLED'].includes(o.status),red:o.status==='AFTERSALE'}">{{labels[o.status]}}</text></view><view class="row order-item clickable" @click="go('orders/detail',{id:o.id})"><GameArt variant="mini" class="mini-cover" :game="o.game" /><view class="stack flex-1"><text class="bold">{{o.title}}</text><text class="muted tiny">{{gameServerLabel(o)}} · {{o.quantity}} 件</text><text class="price">¥{{money(o.amountCents)}}</text></view></view><view v-if="['IN_PROGRESS','REVIEW'].includes(o.status)" class="order-progress"><text class="muted tiny">已完成 {{o.progress}}%</text><view class="step-line"><view :style="{width:o.progress+'%'}" /></view></view><view class="order-actions"><button class="ui-button btn small outline" @click="chatWith(role==='buyer'?o.workerId:o.buyerId,o.listingId)">联系{{role==='buyer'?'卖家':'买家'}}</button><button class="ui-button btn small" @click="go('orders/detail',{id:o.id})">{{o.status==='WAIT_PAY'&&role==='buyer'&&session.config?.paymentsEnabled===true?'去付款':o.status==='REVIEW'&&role==='buyer'?'查看成果':'查看订单'}}</button></view></view><button v-if="items.length<total" class="ui-button load-more" @click="more">加载更多</button></view></AppShell></template>
<script setup>
import {gameServerLabel} from '../../lib/playerTrade';import {ref} from 'vue';import {onLoad,onShow,onReachBottom} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import GameArt from '../../components/GameArt.vue';import AppIcon from '../../components/AppIcon.vue';import StateView from '../../components/StateView.vue';import {go,money,labels,requireLogin,chatWith,session} from '../../lib/api';import {useList} from '../../lib/useList'
const role=ref('buyer'),status=ref('ALL'),keyword=ref(''),statuses=[{label:'全部',value:'ALL'},{label:'待付款',value:'WAIT_PAY'},{label:'待交付',value:'WAIT_DELIVERY'},{label:'待收货',value:'WAIT_CONFIRM'},{label:'历史待开始',value:'WAIT_START'},{label:'历史进行中',value:'IN_PROGRESS'},{label:'历史待验收',value:'REVIEW'},{label:'已完成',value:'COMPLETED'},{label:'售后 / 退款',value:'AFTERSALE'},{label:'已取消',value:'CANCELLED'}];const{items,loading,error,total,load,more}=useList('/boost/orders',()=>({role:role.value,status:status.value,keyword:keyword.value}));onLoad(q=>{role.value=q.role||'buyer';status.value=q.status||'ALL'});onShow(()=>{if(requireLogin())load()});onReachBottom(more)
</script>

<style scoped>.segmented .ui-button{display:flex;align-items:center;justify-content:center;text-align:center;flex:1;min-width:0}.tabs{gap:0}.tabs .ui-button{display:flex;align-items:center;justify-content:center;text-align:center;min-width:72px;padding:0 12px}.tabs button.selected::after{left:50%;transform:translateX(-50%)}.order-search{margin-top:10px;min-height:34px}.order-search input{height:34px;font-size:12px}.order-search .text-button{min-height:34px}.order-item{margin-top:10px;gap:10px}.order-peer{gap:7px}.order-peer text{font-size:14px}.order-item .price{font-size:21px}.order-progress{margin-top:9px}.order-progress .step-line{margin-top:4px}.order-actions{margin-top:12px}.order-actions .btn{flex:1;min-height:34px}.card{padding:12px}.pad>.card{margin-bottom:10px}</style>
